using System;

namespace Framework.AI.Decision
{
    /// <summary>
    /// 行動候補を評価する個別の評価要素。
    /// </summary>
    /// <typeparam name="TContext">意思決定に使用する情報の型</typeparam>
    /// <remarks>
    /// 評価処理は状態を変更しない処理とする。
    /// </remarks>
    public sealed class UtilityConsideration<TContext>
    {
        /// <summary>
        /// 評価値を計算する処理。
        /// </summary>
        private readonly Func<TContext, float> evaluator;

        /// <summary>
        /// 評価要素の名前を取得する。
        /// </summary>
        public string Name { get; }

        /// <summary>
        /// 評価要素を生成する。
        /// </summary>
        /// <param name="name">評価要素の名前</param>
        /// <param name="evaluator">評価値を計算する処理</param>
        /// <exception cref="ArgumentException">
        /// 名前が空の場合に発生する。
        /// </exception>
        /// <exception cref="ArgumentNullException">
        /// 評価処理がnullの場合に発生する。
        /// </exception>
        public UtilityConsideration(
            string name,
            Func<TContext, float> evaluator)
        {
            if (string.IsNullOrWhiteSpace(name))
            {
                throw new ArgumentException(
                    "評価要素名が指定されていません。",
                    nameof(name));
            }

            if (evaluator == null)
            {
                throw new ArgumentNullException(
                    nameof(evaluator));
            }

            Name = name;
            this.evaluator = evaluator;
        }

        /// <summary>
        /// 指定された情報から評価値を計算する。
        /// </summary>
        /// <param name="context">意思決定に使用する情報</param>
        /// <returns>0から1の評価値</returns>
        /// <remarks>
        /// 評価処理が発生させた例外は呼び出し元へ通知する。
        /// </remarks>
        public float Evaluate(TContext context)
        {
            return UtilityMath.Clamp01(
                evaluator(context));
        }
    }
}
